using FreeSql.DataAnnotations;
using VelrixWorkHub.Domain;
namespace VelrixWorkHub.Infrastructure.SalesOrders;
[Table(Name = "ErpSalesOrder")] public sealed class SalesOrderRecord { [Column(IsPrimary=true,Position=1)] public Guid Id {get;set;} [Column(StringLength=80,IsNullable=false,Position=2)] public string OrderNo {get;set;}=string.Empty; [Column(Position=3)] public Guid CustomerId {get;set;} [Column(Position=4)] public Guid ProductId {get;set;} [Column(Position=5)] public Guid? ContractId {get;set;} [Column(Position=6)] public Guid? PmpProjectId {get;set;} [Column(Position=7,DbType="date",IsNullable=false)] public DateTime OrderDate {get;set;} [Column(Position=8,DbType="numeric(12,2)")] public decimal Quantity {get;set;} [Column(Position=9,DbType="numeric(12,2)")] public decimal UnitPrice {get;set;} [Column(MapType=typeof(string),StringLength=50,Position=10)] public SalesOrderStatus Status {get;set;} [Column(Position=11,DbType="date")] public DateTime? DueDate {get;set;} }
